--       database version OVERRIDES the static TypeScript version.

BEGIN;

-- ─────────────────────────────────────────────────────────────────────────────
-- COMPUTERS (ids 11-15, static from allProducts.ts, Unsplash images)
-- ─────────────────────────────────────────────────────────────────────────────
INSERT INTO products (legacy_override_id, name, title, description, price, primary_image_url, rating, category, brand, is_active, features, specifications)
VALUES
(11, 'MacBook Pro 16', 'MacBook Pro 16-inch', 'The most powerful MacBook Pro ever. Supercharged by M-series chip for exceptional performance and battery life.', 2499, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=500&h=500&fit=crop', 4.9, 'Computers', 'Apple', true, '["M-series chip","16-inch Liquid Retina XDR display","Up to 22 hours battery","Up to 128GB unified memory","ProRes video support","MagSafe 3 charging"]', '[{"label":"Display","value":"16-inch Liquid Retina XDR"},{"label":"Chip","value":"Apple M-series"},{"label":"Battery","value":"Up to 22 hours"},{"label":"Memory","value":"Up to 128GB unified"},{"label":"Storage","value":"Up to 8TB SSD"}]'),
(12, 'Dell XPS 15', 'Dell XPS 15 Laptop', 'Premium 15-inch laptop with OLED display, Intel Core processor, and thin & light design for professionals.', 1899, 'https://images.unsplash.com/photo-1593642632823-8f785ba67e45?w=500&h=500&fit=crop', 4.7, 'Computers', 'Dell', true, '["Intel Core i7/i9 processor","15.6-inch OLED display","NVIDIA GeForce RTX graphics","Up to 86Wh battery","Thunderbolt 4 ports","Fingerprint reader"]', '[{"label":"Display","value":"15.6-inch OLED"},{"label":"Processor","value":"Intel Core i7/i9"},{"label":"Graphics","value":"NVIDIA GeForce RTX"},{"label":"Battery","value":"86Wh"},{"label":"Ports","value":"Thunderbolt 4"}]'),
(13, 'HP Spectre x360', 'HP Spectre x360 Convertible Laptop', 'Ultra-premium 2-in-1 convertible laptop with OLED display, Intel Evo platform, and gem-cut design.', 1299, 'https://images.unsplash.com/photo-1525547719571-a2d4ac8945e2?w=500&h=500&fit=crop', 4.6, 'Computers', 'HP', true, '["Intel Evo platform","OLED 2-in-1 convertible","360-degree hinge","Intel Iris Xe graphics","Fingerprint reader","Bang & Olufsen audio"]', '[{"label":"Type","value":"2-in-1 Convertible"},{"label":"Platform","value":"Intel Evo"},{"label":"Display","value":"OLED"},{"label":"Hinge","value":"360-degree"},{"label":"Audio","value":"Bang & Olufsen"}]'),
(14, 'Lenovo ThinkPad X1 Carbon', 'Lenovo ThinkPad X1 Carbon', 'Business ultrabook with legendary ThinkPad reliability, Intel Core Ultra processor, and military-grade durability.', 1499, 'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?w=500&h=500&fit=crop', 4.8, 'Computers', 'Lenovo', true, '["Intel Core Ultra processor","14-inch IPS display","Military-grade durability (MIL-STD-810H)","Up to 15 hours battery","Thunderbolt 4","ThinkPad keyboard"]', '[{"label":"Processor","value":"Intel Core Ultra"},{"label":"Display","value":"14-inch IPS"},{"label":"Durability","value":"MIL-STD-810H"},{"label":"Battery","value":"Up to 15 hours"},{"label":"Keyboard","value":"ThinkPad backlit"}]'),
(15, 'ASUS ROG Zephyrus', 'ASUS ROG Zephyrus Gaming Laptop', 'Powerful gaming laptop with AMD Ryzen processor, NVIDIA RTX graphics, and high-refresh display for competitive gaming.', 1999, 'https://images.unsplash.com/photo-1603302576837-37561b2e2302?w=500&h=500&fit=crop', 4.7, 'Computers', 'ASUS', true, '["AMD Ryzen 9 processor","NVIDIA GeForce RTX 4090","165Hz QHD display","ROG Intelligent Cooling","Dolby Atmos audio","USB-C charging"]', '[{"label":"Processor","value":"AMD Ryzen 9"},{"label":"GPU","value":"NVIDIA RTX 4090"},{"label":"Display","value":"165Hz QHD"},{"label":"Cooling","value":"ROG Intelligent Cooling"},{"label":"Audio","value":"Dolby Atmos"}]')
ON CONFLICT (legacy_override_id) DO UPDATE SET
  name=EXCLUDED.name, title=EXCLUDED.title, description=EXCLUDED.description,
