-- ─────────────────────────────────────────────────────────────────────────────
-- PHONE ACCESSORIES (power banks, stands, chargers)
-- ─────────────────────────────────────────────────────────────────────────────
INSERT INTO products (legacy_override_id, name, title, description, price, primary_image_url, rating, category, brand, is_active, features, specifications, secondary_categories)
VALUES
(101, 'Hoco Q37 IntelligentBalance 10000mAh Power Bank', 'Hoco Q37 Fast Charging Power Bank (10000mAh)', 'Stay powered up wherever you go with the Hoco Q37 IntelligentBalance Power Bank. Features built-in cables, 22.5W fast charging, and a digital display showing remaining battery percentage.', 20, 'https://placehold.co/500x500/0f172a/ffffff?text=Hoco+Q37', 4.8, 'Charging', 'Hoco', true, '["10000mAh Capacity","22.5W, PD 20W, QC3.0 Fast Charging","Built-in Lightning and USB-C cables","4 outputs, 2 inputs","Digital battery percentage display","18-Month Warranty"]', '[{"label":"Capacity","value":"10000mAh"},{"label":"Fast Charging","value":"22.5W, PD 20W, QC3.0"},{"label":"Outputs","value":"4"},{"label":"Inputs","value":"2"},{"label":"Built-in Cables","value":"Lightning, USB-C"},{"label":"Display","value":"Digital Battery Percentage"}]', '["Accessories"]'),
(102, 'Dobe Dual Charging Dock for PS4 Controllers', 'Dobe Dual Charging Dock for PlayStation 4 Controllers', 'Keep your gaming sessions uninterrupted with the Dobe Dual Charging Dock for PS4. Charges two DUALSHOCK 4 controllers simultaneously with LED charging indicators.', 10, 'https://placehold.co/500x500/0f172a/ffffff?text=Dobe+PS4+Dock', 4.7, 'Gaming', 'Dobe', true, '["Dual Controller Charging","Compatible with PS4, PS4 Slim, PS4 Pro","LED charging indicators","Stable dock design","Easy drop-in charging"]', '[{"label":"Compatibility","value":"PS4, PS4 Slim, PS4 Pro"},{"label":"Capacity","value":"2 controllers"},{"label":"Indicators","value":"LED status"}]', '["Gaming Accessories"]'),
(103, 'Dobe Charging Dock for PS5 Controllers', 'Dobe Charging Dock for PlayStation 5 DualSense Controllers', 'Power up your next-gen gaming with the Dobe Charging Dock for PS5. Charges two DualSense controllers with overcharge protection and PS5-matching design.', 10, 'https://placehold.co/500x500/0f172a/ffffff?text=Dobe+PS5+Dock', 4.8, 'Gaming', 'Dobe', true, '["Charges 2 DualSense controllers","PS5 aesthetic design","Overcharge protection","Click-in secure connection","Compact design"]', '[{"label":"Compatibility","value":"PS5 DualSense"},{"label":"Capacity","value":"2 controllers"},{"label":"Protection","value":"Overcharge protection"}]', '["Gaming Accessories"]'),
(104, 'Hoco J132A IntelligentBalance 20000mAh Power Bank', 'Hoco J132A High-Capacity Power Bank (20000mAh)', 'High-capacity 20000mAh powerhouse with 4-in-1 built-in cables, 22.5W fast charging, and LED digital display. Ideal for heavy users and travelers.', 30, 'https://placehold.co/500x500/0f172a/ffffff?text=Hoco+J132A', 4.9, 'Charging', 'Hoco', true, '["20000mAh Capacity","4-in-1 Built-in Cables (USB-C, Lightning, Micro-USB, USB-A)","22.5W Super Fast + PD 20W Charging","LED Digital Display","Charge up to 4 devices at once"]', '[{"label":"Capacity","value":"20000mAh"},{"label":"Fast Charging","value":"22.5W, PD 20W"},{"label":"Built-in Cables","value":"USB-C, Lightning, Micro-USB, USB-A"},{"label":"Display","value":"LED Digital"}]', '["Accessories"]'),
(105, 'Kakusiga Folding Rotatable Desktop Stand', 'Kakusiga 360° Rotatable Folding Desktop Stand', 'Versatile 360° rotating phone stand with adjustable height and angle. Foldable for travel, compatible with 4.7-7 inch devices.', 10, 'https://placehold.co/500x500/0f172a/ffffff?text=Kakusiga+Stand', 4.6, 'Accessories', 'Kakusiga', true, '["360° Rotating Base","Fully Foldable Design","Adjustable Height & Angle","Weighted non-slip base","Universal 4.7-7 inch compatibility"]', '[{"label":"Rotation","value":"360°"},{"label":"Design","value":"Foldable"},{"label":"Compatibility","value":"4.7\" to 7\" devices"}]', '["Phone Accessories"]'),
(109, '25W USB-C Power Adapter with USB-C to Lightning Cable', '25W USB-C Fast Charger Set (Adapter & Cable)', 'Complete fast charging set with 25W USB-C power adapter and USB-C to Lightning cable. Fast-charges iPhone to 50% in ~30 minutes.', 15, 'https://placehold.co/500x500/0f172a/ffffff?text=25W+USB-C+Set', 4.8, 'Charging', 'Apple', true, '["25W Fast Charging","Complete set: adapter + USB-C to Lightning cable","Compatible with iPhone 14/13/12/11 Pro/Pro Max","Compact portable design"]', '[{"label":"Power","value":"25W"},{"label":"Cable","value":"USB-C to Lightning"},{"label":"Compatibility","value":"iPhone 14/13/12/11"}]', '["Accessories"]'),
(112, 'Hoco 22.5W 10000mAh Power Bank', 'Hoco 22.5W Super Fast Charging Power Bank (10000mAh)', 'Compact 10000mAh power bank with 22.5W super fast charging. Charges smartphone to 50% in under 30 minutes. Multiple port support.', 20, 'https://placehold.co/500x500/0f172a/ffffff?text=Hoco+22.5W', 4.8, 'Charging', 'Hoco', true, '["22.5W Super Fast Charging","10000mAh capacity","Multiple outputs","LED battery indicator","Compact design"]', '[{"label":"Capacity","value":"10000mAh"},{"label":"Fast Charging","value":"22.5W"},{"label":"Design","value":"Compact"}]', '["Accessories"]')
ON CONFLICT (legacy_override_id) DO UPDATE SET
