  secondary_categories=EXCLUDED.secondary_categories, updated_at=NOW();

-- ─────────────────────────────────────────────────────────────────────────────
-- AUDIO PRODUCTS
-- ─────────────────────────────────────────────────────────────────────────────
INSERT INTO products (legacy_override_id, name, title, description, price, primary_image_url, rating, category, brand, is_active, features, specifications)
VALUES
(106, 'Apple AirPods', 'Apple AirPods with MagSafe Charging Case', 'Experience the magic of Apple AirPods with Spatial Audio, dynamic head tracking, and a contoured design. Over 30 hours total listening time with MagSafe case.', 10, 'https://placehold.co/500x500/0f172a/ffffff?text=AirPods', 4.9, 'Audio', 'Apple', true, '["Spatial Audio with dynamic head tracking","Adaptive EQ","Contoured ergonomic design","Force sensor controls","IPX4 sweat & water resistant","30+ hours total with MagSafe case","MagSafe & wireless charging","12-Month warranty"]', '[{"label":"Audio","value":"Spatial Audio"},{"label":"EQ","value":"Adaptive EQ"},{"label":"Resistance","value":"IPX4"},{"label":"Battery","value":"30+ hours total"},{"label":"Charging","value":"MagSafe, wireless"}]'),
(107, 'Galaxy Buds6 Pro (White)', 'Samsung Galaxy Buds6 Pro Wireless Earbuds - White', 'Samsung Galaxy Buds6 Pro in White. True wireless earbuds with ergonomic fit, touch controls, and built-in microphone for hands-free calls.', 15, 'https://placehold.co/500x500/0f172a/ffffff?text=Galaxy+Buds6+White', 4.7, 'Audio', 'Samsung', true, '["True Wireless Design","Ergonomic fit","Touch controls","Built-in microphone","Compact charging case","Bluetooth connectivity"]', '[{"label":"Color","value":"White"},{"label":"Design","value":"True wireless"},{"label":"Controls","value":"Touch"},{"label":"Mic","value":"Built-in"}]'),
(108, 'Galaxy Buds6 Pro (Black)', 'Samsung Galaxy Buds6 Pro Wireless Earbuds - Black', 'Samsung Galaxy Buds6 Pro in Black. True wireless earbuds with ergonomic fit, touch controls, and built-in microphone for hands-free calls.', 15, 'https://placehold.co/500x500/0f172a/ffffff?text=Galaxy+Buds6+Black', 4.7, 'Audio', 'Samsung', true, '["True Wireless Design","Ergonomic fit","Touch controls","Built-in microphone","Compact charging case","Bluetooth connectivity"]', '[{"label":"Color","value":"Black"},{"label":"Design","value":"True wireless"},{"label":"Controls","value":"Touch"},{"label":"Mic","value":"Built-in"}]'),
(110, 'JBL Tune 903BT V5.3 Wireless Headphone', 'JBL Tune 903BT V5.3 Wireless Over-Ear Headphone', 'Premium JBL Pure Bass sound with Bluetooth 5.3. 40 hours battery life, 10-min quick charge for 4 hours, multi-point connection, and built-in microphone.', 16, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+903BT', 4.7, 'Audio', 'JBL', true, '["Bluetooth 5.3","JBL Pure Bass Sound","Up to 40 hours battery","Quick charge: 10min = 4hrs","Multi-point connection","Built-in microphone","Foldable design"]', '[{"label":"Bluetooth","value":"5.3"},{"label":"Battery","value":"40 hours"},{"label":"Quick Charge","value":"10min = 4hrs"},{"label":"Connection","value":"Multi-point"}]'),
(111, 'Apple AirPods 4 (Copy A)', 'Apple AirPods 4 (Copy A) - H2 Chip Sound Experience', 'High-quality AirPods 4 replica featuring the H2 chip experience with Spatial Audio, Personalized Spatial Audio, Adaptive EQ, and MagSafe charging. IPX4 resistance.', 20, 'https://placehold.co/500x500/0f172a/ffffff?text=AirPods+4+Copy', 4.9, 'Audio', 'Apple', true, '["H2 Chip audio processing","Spatial Audio with dynamic head tracking","Personalized Spatial Audio","Adaptive EQ","IPX4 sweat & water resistant","MagSafe charging case","30+ hours total battery","Available with ANC option"]', '[{"label":"Chip","value":"H2"},{"label":"Audio","value":"Spatial Audio"},{"label":"Resistance","value":"IPX4"},{"label":"Battery","value":"30+ hours total"},{"label":"Charging","value":"MagSafe"}]'),
(127, 'Apple AirPods Pro 3', 'Apple AirPods Pro 3 - White (AAP3-WT)', 'Next-gen AirPods Pro 3 with heart rate sensing, studio-quality recording, ANC with Adaptive Audio, IP57 water resistance, up to 32 hours total battery, and USB-C charging.', 287, 'https://placehold.co/500x500/0f172a/ffffff?text=AirPods+Pro+3', 5.0, 'Audio', 'Apple', true, '["Heart Rate Sensing","Workout Tracking (50+ types)","Studio-quality recording","ANC with Adaptive Audio","Adaptive Transparency","Personalized Spatial Audio","8hrs (ANC) + 24hrs case = 32hrs total","IP57 water resistance","Bluetooth 5.4","USB-C charging"]', '[{"label":"Model","value":"AAP3-WT (White)"},{"label":"Bluetooth","value":"5.4"},{"label":"Battery (ANC)","value":"8 hours"},{"label":"Battery (Case)","value":"24 hours"},{"label":"Total Battery","value":"32 hours"},{"label":"Charging","value":"USB-C + wireless"},{"label":"Water Resistance","value":"IP57"}]'),
(128, 'Apple AirPods 4 (Original)', 'Apple AirPods 4 (Original) - Official', 'Official Apple AirPods 4 with H2 chip, Personalized Spatial Audio, Adaptive EQ, IP54 resistance, USB-C charging, and up to 30 hours total battery. Available in Standard and ANC variants.', 150, 'https://placehold.co/500x500/0f172a/ffffff?text=AirPods+4+Original', 4.9, 'Audio', 'Apple', true, '["Apple H2 Chip","Redesigned ergonomic fit","Personalized Spatial Audio","Adaptive EQ","Voice Isolation for calls","IP54 (earbuds + case)","USB-C charging","Force sensor controls","Hey Siri always-on","Bluetooth 5.3","Find My support"]', '[{"label":"Chip","value":"Apple H2"},{"label":"Resistance","value":"IP54 earbuds + case"},{"label":"Battery","value":"30 hours total"},{"label":"Charging","value":"USB-C"},{"label":"Bluetooth","value":"5.3"},{"label":"In Box","value":"AirPods 4, USB-C case, documentation"}]'),
(129, 'Apple AirPods Pro (2nd Generation) with USB-C', 'Apple AirPods Pro (2nd Generation) - USB-C Charging', 'Premium AirPods Pro 2 with H2 chip, 2x ANC, Adaptive Audio, Conversation Awareness, Personalized Spatial Audio, hearing health features, 30hrs total battery, and IP54 USB-C case.', 215, 'https://placehold.co/500x500/0f172a/ffffff?text=AirPods+Pro+2+USBC', 5.0, 'Audio', 'Apple', true, '["Apple H2 Chip","Up to 2x Active Noise Cancellation","Adaptive Audio","Conversation Awareness","Personalized Spatial Audio","Hearing Test & Hearing Aid features","6hrs (ANC) + 24hrs case = 30hrs total","IP54 (earbuds + case)","USB-C MagSafe case","Bluetooth 5.3","Lossless audio for Vision Pro"]', '[{"label":"Chip","value":"Apple H2"},{"label":"ANC","value":"2x improvement"},{"label":"Battery (ANC)","value":"6 hours"},{"label":"Total Battery","value":"30 hours"},{"label":"Charging","value":"USB-C, MagSafe, Qi, Apple Watch charger"},{"label":"Resistance","value":"IP54 (earbuds + case)"},{"label":"Bluetooth","value":"5.3"}]'),
(140, 'JBL TUNE110 Earphones', 'JBL TUNE110 In-Ear Headphones with Pure Bass Sound', 'Lightweight JBL TUNE110 in-ear headphones with 9mm drivers for JBL Pure Bass sound. Tangle-free flat cable with single-button remote and microphone. Available in Black, Blue, White.', 10, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+TUNE110', 4.5, 'Audio', 'JBL', true, '["JBL Pure Bass Sound","1-Button remote with microphone","Tangle-free flat cable","9mm drivers","Lightweight & compact","3.5mm jack connection"]', '[{"label":"Driver","value":"9.0mm"},{"label":"Frequency","value":"20Hz–20kHz"},{"label":"Connection","value":"3.5mm Jack"},{"label":"Cable","value":"Tangle-free flat"}]'),
(141, 'JBL Tune 520BT Wireless Headphones', 'JBL Tune 520BT Wireless On-Ear Headphones', 'JBL Pure Bass wireless headphones with Bluetooth 5.3, up to 57 hours battery, 5-minute quick charge for 3 hours, multi-point connection, and voice assistant support.', 45, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+520BT', 4.7, 'Audio', 'JBL', true, '["JBL Pure Bass Sound","Bluetooth 5.3","57 hours battery life","Quick Charge: 5min = 3hrs","Multi-point connection","Voice aware feature","Siri/Google Assistant","Foldable lightweight design"]', '[{"label":"Bluetooth","value":"5.3"},{"label":"Driver","value":"33mm"},{"label":"Battery","value":"57 hours"},{"label":"Charging","value":"2 hours"},{"label":"Weight","value":"157g"},{"label":"Impedance","value":"30 ohm"}]'),
(142, 'JBL Tune 720BT Wireless Headphones', 'JBL Tune 720BT Wireless Over-Ear Headphones', 'JBL Pure Bass over-ear wireless headphones with Bluetooth 5.3, up to 76 hours battery, 5-minute quick charge, multi-point connection, and JBL Headphones App support.', 57, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+720BT', 4.8, 'Audio', 'JBL', true, '["JBL Pure Bass Sound","Bluetooth 5.3","76 hours battery life","Quick Charge: 5min = 3hrs","Multi-point connection","JBL Headphones App support","Voice Aware","Foldable lightweight design"]', '[{"label":"Bluetooth","value":"5.3"},{"label":"Driver","value":"40mm"},{"label":"Battery","value":"76 hours"},{"label":"Charging","value":"2 hours"},{"label":"Weight","value":"220g"},{"label":"Impedance","value":"32 ohm"}]'),
(143, 'JBL Go 4 Ultra-Portable Bluetooth Speaker', 'JBL Go 4 Ultra-Portable Waterproof Bluetooth Speaker', 'Palm-sized IP67 waterproof Bluetooth 5.3 speaker with clear JBL Pro Sound, up to 7 hours playtime, redesigned loop, stereo pairing, and vibrant color options.', 60, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+Go+4', 4.9, 'Audio', 'JBL', true, '["Ultra-portable JBL Pro Sound","7 hours playtime","IP67 waterproof & dustproof","Bluetooth 5.3","Stereo pairing (2 Go 4s)","Auracast multi-speaker","Redesigned integrated loop","Made with recycled materials"]', '[{"label":"Output","value":"4.2W"},{"label":"Frequency","value":"90Hz–20kHz"},{"label":"Bluetooth","value":"5.3"},{"label":"Battery","value":"7 hours"},{"label":"Charging","value":"3 hours"},{"label":"Rating","value":"IP67"},{"label":"Weight","value":"0.19kg"}]'),
(144, 'JBL PartyBox Club 120', 'JBL PartyBox Club 120 Portable Speaker with Lights', 'Party speaker with 160W JBL Pro Sound, starry light show synced to music, mic & guitar inputs, replaceable battery, 12 hours playtime, IPX4, and AI Sound Boost.', 370, 'https://placehold.co/500x500/0f172a/ffffff?text=JBL+PartyBox+120', 4.9, 'Audio', 'JBL', true, '["160W Powerful JBL Pro Sound","Futuristic lightshow (starry lights, strobe)","12 hours playtime","Replaceable battery","Mic & guitar inputs","IPX4 splashproof","AI Sound Boost","Stereo pairing & Auracast multi-speaker","JBL PartyBox App"]', '[{"label":"Output","value":"160W"},{"label":"Frequency","value":"40Hz–20kHz"},{"label":"Bluetooth","value":"5.3"},{"label":"Battery","value":"12 hours"},{"label":"Charging","value":"3.5 hours"},{"label":"Rating","value":"IPX4"},{"label":"Weight","value":"11.05kg"}]')
